import math

def is_power_of_5(N):
    if N <= 0:
        return False
    if N == 1:
        return True
    while N % 5 == 0:
        N //= 5
    return N == 1

solutions = []
for n in range(3, 21):
    X = (2**n) - 3
    if is_power_of_5(X):
        # Find the exponent k such that X = 5^k
        k = int(math.log(X, 5))
        solutions.append((n, k))

print("Found solutions (n, k):", solutions)

